// В TypeScript нет встроенной кучи — пишем свою.
// Двоичная куча хранится в массиве: дети узла i — 2i + 1 и 2i + 2, родитель — (i - 1) >> 1.
class Heap<T> {
  private data: T[] = [];

  // less(a, b) === true, если a должен стоять ближе к вершине, чем b.
  // (a, b) => a < b — min-куча, (a, b) => a > b — max-куча
  constructor(private less: (a: T, b: T) => boolean) {}

  size(): number {
    return this.data.length;
  }

  // Вершина кучи (минимум или максимум) за O(1)
  peek(): T | undefined {
    return this.data[0];
  }

  // Добавление за O(log n): кладём в конец и «поднимаем» вверх
  push(value: T): void {
    const a = this.data;
    a.push(value);
    let i = a.length - 1;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      // Родитель уже «лучше» — порядок кучи восстановлен
      if (!this.less(a[i], a[parent])) break;
      [a[i], a[parent]] = [a[parent], a[i]];
      i = parent;
    }
  }

  // Извлечение вершины за O(log n): на её место ставим последний элемент и «топим» его вниз
  pop(): T | undefined {
    const a = this.data;
    const top = a[0];
    const last = a.pop();
    if (a.length > 0 && last !== undefined) {
      a[0] = last;
      let i = 0;
      while (true) {
        const l = 2 * i + 1;
        const r = l + 1;
        // Выбираем «лучшего» из узла и двух его детей
        let best = i;
        if (l < a.length && this.less(a[l], a[best])) best = l;
        if (r < a.length && this.less(a[r], a[best])) best = r;
        if (best === i) break;
        [a[i], a[best]] = [a[best], a[i]];
        i = best;
      }
    }
    return top;
  }
}

function kSmallestPairs(nums1: number[], nums2: number[], k: number): number[][] {
  // В куче — кандидаты [сумма, i, j]; меньшая сумма ближе к вершине
  const heap = new Heap<[number, number, number]>((a, b) => a[0] < b[0]);

  // Для каждого i (не больше k штук) самая маленькая пара — (nums1[i], nums2[0])
  for (let i = 0; i < Math.min(k, nums1.length); i++) {
    heap.push([nums1[i] + nums2[0], i, 0]);
  }

  const result: number[][] = [];
  while (result.length < k && heap.size() > 0) {
    // Достаём пару с минимальной суммой среди всех кандидатов
    const [, i, j] = heap.pop()!;
    result.push([nums1[i], nums2[j]]);

    // Следующий кандидат в «строке» i — тот же nums1[i] со следующим nums2[j + 1]
    if (j + 1 < nums2.length) {
      heap.push([nums1[i] + nums2[j + 1], i, j + 1]);
    }
  }

  return result;
}

// Время: O(k log k)
// Память: O(k)
